import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Load brushed metal texture
  let material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
  });

  // Async texture load
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.colorNode = texture(tex, uv());
      material.needsUpdate = true;
    });
  }

  const mesh = new THREE.Mesh(geometry, material);

  // Create text label from config
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textItem = textItems.find((item) => item.role === 'headline') || textItems[0];
  const textContent = textItem?.text || 'Journal 1';

  // Render headline text
  const textObj = ctx.fontAtlas.createText(textContent, {
    fontSize: 39,
    color: '#16161d',
    align: 'left',
  });

  // Position text above/centered relative to plane
  textObj.position.set(0, 0.6, 0.01);
  textObj.scale.set(0.5, 0.5, 0.5);

  // Group plane + text
  const group = new THREE.Group();
  group.add(mesh);
  group.add(textObj);

  // Apply scene position
  if (config.scenePosition) {
    group.position.copy(config.scenePosition);
  }
  if (config.sceneRotation) {
    group.rotation.copy(config.sceneRotation);
  }
  if (config.sceneScale) {
    group.scale.copy(config.sceneScale);
  }

  // Cleanup handler
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  group.userData.handlers = {};

  return group;
}
